instance_norm_divide_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

__global__ void instance_norm_divide_kernel(
    const float* input, 
    float* output,
    const float* weight, 
    const float* bias,
    const float* running_mean,
    const float* running_var,
    int batch_size, 
    int channels, 
    int height, 
    int width,
    float divide_by,
    float eps,
    bool affine,
    bool track_running_stats
) {
    // Process one channel per thread block
    int c = blockIdx.x;
    int n = blockIdx.y;

    if (n >= batch_size || c >= channels) return;

    int hw = height * width;
    int base_idx = (n * channels + c) * hw;

    // Share memory for reduction
    const int BLOCK_SIZE = 256;
    __shared__ float smem[BLOCK_SIZE];
    __shared__ float smem2[BLOCK_SIZE];

    // Compute mean
    float sum = 0.0f;
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        sum += input[base_idx + i];
    }

    smem[threadIdx.x] = sum;
    __syncthreads();

    // Reduce within block
    for (int s = BLOCK_SIZE / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            smem[threadIdx.x] += smem[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = smem[0] / hw;
    __syncthreads();

    // Compute variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        float val = input[base_idx + i] - mean;
        var_sum += val * val;
    }

    smem2[threadIdx.x] = var_sum;
    __syncthreads();

    for (int s = BLOCK_SIZE / 2; s > 0; s /= 2) {
        if (threadIdx.x < s) {
            smem2[threadIdx.x] += smem2[threadIdx.x + s];
        }
        __syncthreads();
    }

    float var = smem2[0] / hw;
    float inv_std = 1.0f / sqrtf(var + eps);

    // Get weight and bias
    float w = affine ? weight[c] : 1.0f;
    float b = affine ? bias[c] : 0.0f;

    // Combine with divide operation
    float combined_weight = w / divide_by;
    float combined_bias = b / divide_by;

    // Normalize and output
    for (int i = threadIdx.x; i < hw; i += BLOCK_SIZE) {
        float normalized = (input[base_idx + i] - mean) * inv_std;
        output[base_idx + i] = combined_weight * normalized + combined_bias;
    }
}

torch::Tensor instance_norm_divide_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float divide_by,
    float eps,
    bool affine,
    bool track_running_stats
) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::zeros_like(input);

    const int block_size = 256;
    dim3 block(block_size);
    dim3 grid(channels, batch_size);

    instance_norm_divide_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        divide_by,
        eps,
        affine,
        track_running_stats
    );

    return output;
}
"""

